(853462, 96766, 12583, '<td valign="top">A bit too blurry for my tastes.</td>', 'A bit too blurry for my tastes.', '2004-08-11 01:35:10.000000', NULL, 1),
(853464, 96335, 23939, '<td valign="top">very noisy</td>', 'very noisy', '2004-08-11 01:35:17.000000', NULL, 1),
(853466, 96702, 1368, '<td valign="top">Very cool! great colors - 10</td>', 'Very cool! great colors - 10', '2004-08-11 01:36:00.000000', NULL, 1),
