(853486, 96252, 20779, '<td valign="top">Extremely cool. I love this. Perfect clarity.</td>', 'Extremely cool. I love this. Perfect clarity.', '2004-08-11 01:40:20.000000', NULL, 1),
(853487, 96799, 10339, '<td valign="top">Very nicely done. I love the rust colors on the trestle - and the misty shadows of the trees in the distance. The contrast from the bottom of the frame to the upper right is fantastic.</td>', 'Very nicely done. I love the rust colors on the trestle - and the misty shadows of the trees in the distance. The contrast from the bottom of the frame to the upper right is fantastic.', '2004-08-11 01:40:21.000000', NULL, 1),
(853489, 96763, 7322, '<td valign="top">It took me awhile to spot a vanishing point but I''m guessing you were going for converging parallels in the crop rows. That''s not working quite powerfully, IMO. It''s a nice landscape photo though.</td>', 'It took me awhile to spot a vanishing point but I''m guessing you were going for converging parallels in the crop rows. That''s not working quite powerfully, IMO. It''s a nice landscape photo though.', '2004-08-11 01:41:06.000000', NULL, 1),
(853490, 96446, 20779, '<td valign="top">Terrific B &amp; W accomplished.</td>', 'Terrific B & W accomplished.', '2004-08-11 01:41:08.000000', NULL, 1),
