(856960, 96564, 14603, '<td valign="top">Nice abstract quality to this image which sets it apart from others of the same type.<br/>Nicely done</td>', 'Nice abstract quality to this image which sets it apart from others of the same type.Nicely done', '2004-08-12 12:21:30.000000', NULL, 1),
(856965, 96133, 24715, '<td valign="top">Very nice picture, it flows beautifully.</td>', 'Very nice picture, it flows beautifully.', '2004-08-12 12:24:54.000000', NULL, 1),
