(866963, 96871, 245, '<td valign="top">Wow, really beautiful!</td>', 'Wow, really beautiful!', '2004-08-19 02:13:15.000000', NULL, 0),
(867056, 96940, 24911, '<td valign="top">A great effect of VP. Loved the photo. Thought it should be No. 1. Gave it a 10. (:</td>', 'A great effect of VP. Loved the photo. Thought it should be No. 1. Gave it a 10. (:', '2004-08-19 04:25:51.000000', NULL, 0),
(867182, 96222, 4482, '<td valign="top">This is a work of art! The mountains even look like an oil painting!! Now where''s that favs button....  ;-)</td>', 'This is a work of art! The mountains even look like an oil painting!! Now where''s that favs button....  ;-)', '2004-08-19 08:31:56.000000', NULL, 0),
